                        seen.add((yy,xx)); stack.append((yy,xx))
            result.append(cells)
    return result

def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 9]
